module random_pictures (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] m,\n    output reg [31:0] result,\n    output reg done\n);\n    parameter MOD = 32'd1000000007;\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n    reg [1:0] state;\n    reg [7:0] i;\n    reg [7:0] max_idx;\n    reg [7:0] n_minus_1;\n    reg [7:0] m_minus_1;\n    reg [31:0] curr;\n    reg [31:0] next_val;\n    reg [31:0] val_n;\n    reg [31:0] val_m;\n    wire [7:0] n_minus_1_comb = (n > 8'd0) ? n - 8'd1 : 8'd0;\n    wire [7:0] m_minus_1_comb = (m > 8'd0) ? m - 8'd1 : 8'd0;\n    wire [7:0] max_idx_comb = (n_minus_1_comb > m_minus_1_comb) ? n_minus_1_comb : m_minus_1_comb;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            i <= 8'd0;\n            curr <= 32'd0;\n            next_val <= 32'd0;\n            val_n <= 32'd0;\n            val_m <= 32'd0;\n            max_idx <= 8'd0;\n            n_minus_1 <= 8'd0;\n            m_minus_1 <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        n_minus_1 <= n_minus_1_comb;\n                        m_minus_1 <= m_minus_1_comb;\n                        max_idx <= max_idx_comb;\n                        i <= 8'd0;\n                        curr <= 32'd1;\n                        next_val <= 32'd2;\n                        val_n <= (n_minus_1_comb == 8'd0) ? 32'd1 : 32'd0;\n                        val_m <= (m_minus_1_comb == 8'd0) ? 32'd1 : 32'd0;\n                        state <= (max_idx_comb == 8'd0) ? DONE_STATE : COMPUTE;\n                    end\n                end\n                COMPUTE: begin\n                    if (i == n_minus_1 && n_minus_1 != 8'd0) val_n <= curr;\n                    if (i == m_minus_1 && m_minus_1 != 8'd0) val_m <= curr;\n                    i <= i + 8'd1;\n                    if (i == max_idx) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        curr <= next_val;\n                        if (curr + next_val >= MOD) next_val <= curr + next_val - MOD;\n                        else next_val <= curr + next_val;\n                    end\n                end\n                DONE_STATE: begin\n                    begin\n                        reg [31:0] temp_sum;\n                        temp_sum = val_n + val_m;\n                        if (temp_sum >= MOD) temp_sum = temp_sum - MOD;\n                        if (temp_sum == 32'd0) temp_sum = MOD - 32'd1;\n                        else temp_sum = temp_sum - 32'd1;\n                        temp_sum = temp_sum << 1;\n                        if (temp_sum >= MOD) temp_sum = temp_sum - MOD;\n                        result <= temp_sum;\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule